import{_ as s,l as o,o as e,c as l,v as t,p as n,x as i,d as p,i as d,S as _}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"概率与期望 DP","description":"","frontmatter":{"title":"概率与期望 DP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/probability-dp.md","filePath":"cs/probability-dp.md","lastUpdated":1789023840000}'),c={name:"cs/probability-dp.md"};function h(E,a,m,u,P,D){const r=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="概率与期望-dp" tabindex="-1">概率与期望 DP <a class="header-anchor" href="#概率与期望-dp" aria-label="Permalink to &quot;概率与期望 DP&quot;">​</a></h1><div class="epigraph"><p>期望的线性性不要求独立；状态上列方程 $E=1+\\sum p_i E_i$，高斯或拓扑消元，比枚举路径省指数。</p><footer>—— 据 CLRS 第 5 章指示器；[期望线性性](/cs/expectation-linearity) 整理</footer></div><p>上一课<a href="/cs/mobius-inversion">莫比乌斯反演</a>收束数论卷积。主干期望线性性已给指示器。缺口是<strong>状态期望方程</strong>：随机游走步数、直到收集齐的优惠券、博弈随机策略。本单元「多项式、线性与数论」在此结束。下一单元 DP 进阶从状压开始。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>状态 \\(s\\) 的期望 \\(E_s\\) 满足 \\(E_s=a_s+\\sum_{t} P_{st} E_t\\)。无后效则拓扑；有环（随机游走）则线性方程组，高斯 \\(O(n^3)\\) 或高斯–约当。概率 DP：到吸收态的概率，方程同类。不要对每条样本路径 DP。</p><p>优惠券：\\(E=n H_n\\)，不必 DP，但「子集已有」状压期望是后课状压的概率版，本课点名。</p><h3 id="线性性不是独立性" tabindex="-1">线性性不是独立性 <a class="header-anchor" href="#线性性不是独立性" aria-label="Permalink to &quot;线性性不是独立性&quot;">​</a></h3><p>\\(E[\\sum X_i]=\\sum E[X_i]\\) 永远成立。方差、是否同时发生才要独立。期望方程里的 \\(P_{st}\\) 已编码转移，不必事件独立。</p><p><span class="marginnote">指示器见 CLRS 5。随机游走期望见标准概率教材。后课状压 DP 把 \\(s\\) 做成比特掩码，方程或递推都可。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定义状态。列 \\(E\\) 或 \\(p\\)。DAG 倒推；有环高斯。模意义下期望少见，概率可模素数当有理。吸收态边界 0。</p>',11)),(e(),n(_,null,{default:i(()=>[d(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E7%8A%B6%E6%80%81%20s%22%5D%20--%3E%20EQ%5B%22E_s%20%3D%20a%20%2B%20%CE%A3%20p%20E_t%22%5D%0A%20%20EQ%20--%3E%20DAG%5B%22DAG%EF%BC%9A%E5%80%92%E6%8E%A8%22%5D%0A%20%20EQ%20--%3E%20GE%5B%22%E6%9C%89%E7%8E%AF%EF%BC%9A%E9%AB%98%E6%96%AF%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>无限状态要先压缩或有限化。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>全期望定律按一步展开。与 Bellman：随机最短路是另一目标（风险）。本课是期望值或到达概率。与内点无关。与蒙特卡洛：方程给精确有理（分数），模拟给估计。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 MDP 策略迭代全文。不把老虎机当本课（后课 UCB）。后课默认：期望可列状态方程；无环倒推，有环高斯。下一课状态压缩 DP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>期望方程 = 一步展开；线性性不需独立。</li><li>DAG 倒推；有环高斯消元。</li><li>精确值，不是模拟。</li><li>出处：CLRS 第 5 章；全期望定律。</li></ul>',7))])}const f=s(c,[["render",h]]);export{A as __pageData,f as default};
